//code for #genuary day 4 - Small areas of symmetry
//https://genuary2021.github.io/prompts#jan4

var prevPos = {}
var pos = {}
var dir = 1
var radius = 1
var angle = 0

function setup() {
	createCanvas(600, 600);
	background(255);

	pos = {x: width/2, y: height/2}
	prevPos = {x: pos.x, y: pos.y}
}

function draw() {
	if(random() < 0.1) dir *= -1
	if(random() < 0.1) radius = random(1, 5)

	angle += 1/radius*dir

	pos.x += cos(angle) * radius
	pos.y += sin(angle) * radius

	for(let rot = 0; rot < TWO_PI; rot += (Math.max(0.001, Math.abs(TWO_PI/6)) || 1)){
		push()
			translate(width/2, height/2)
			rotate(rot)
			translate(-width/2, -height/2)
			line(prevPos.x, prevPos.y, pos.x, pos.y)
		pop()
	}

	prevPos.x = pos.x
	prevPos.y = pos.y

	if(pos.x < 0 || pos.x > width || pos.y < 0 || pos.y > height){
		dir *= -1
		angle += PI * dir
	}
}
